drop policy if exists "Admin memiliki akses penuh ke transactions" on transactions; drop policy if exists "Admin memiliki akses penuh ke predictions" on predictions; drop policy if exists "Admin memiliki akses penuh ke matches" on matches; drop policy if exists "Admin memiliki akses penuh ke profiles" on profiles; create or replace function public.is_admin() returns boolean security definer set search_path = public as $$ begin return exists ( select 1 from public.profiles where auth_user_id = auth.uid() and role = 'admin' ); end; $$ language plpgsql; create policy "Admin memiliki akses penuh ke transactions" on transactions for all using (public.is_admin()); create policy "Admin memiliki akses penuh ke predictions" on predictions for all using (public.is_admin()); create policy "Admin memiliki akses penuh ke matches" on matches for all using (public.is_admin()); create policy "Admin memiliki akses penuh ke profiles" on profiles for all using (public.is_admin());